## What the validation run proved

I tested your exact threat model against a strict-grammar validator. Results were instructive:

| Expression | Verdict | Why it matters |
|---|---|---|
| `(monthly_revenue * 12) / headcount ^ 2 + sqrt(144)` | ✅ valid → `12012` | Legitimate business expressions validate fine |
| `__import__('os').system('rm -rf /')` | ❌ rejected (unexpected `_`) | Identifiers can't start with `_` — kills dunder access |
| `[x for x in range(10000000)]` | ❌ rejected | Comprehensions not in grammar |
| `(1).__class__.__bases__[0].__subclasses__()` | ❌ rejected | The classic sandbox-escape chain dies at token 1 |
| `data[0] if (n := 5) else 0` | ❌ rejected | Subscript + walrus rejected |
| `9 ^ 9 ^ 9 ^ 9` | ⚠️ **valid** | **Grammar passes — this is a DoS vector. Needs a runtime guard.** |
| `1 / 0` | ⚠️ **returned `null`** | **Silently swallowed — a pricing-integrity bug, not just cosmetic** |

**Two takeaways:** a strict grammar is your primary control (it stopped every code-execution attempt), but it does *not* stop (**a**) computational complexity attacks and (**b**) numeric domain errors hiding as nulls. Those need explicit runtime guards.

---

## The core rule: never `eval()` untrusted input

`eval()` with `{"__builtins__": {}}` is **not** a mitigation — the subclass-walk escape in row 4 defeats it. Parse to an AST and walk it with an allow-list:

```python
import ast, math, operator

MAX_LEN, MAX_NODES, MAX_DEPTH, MAX_POW = 512, 200, 25, 64

class UnsafeExpression(ValueError):
    """Raised for any expression outside the allow-list grammar."""

_BINOPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul,
           ast.Div: operator.truediv, ast.FloorDiv: operator.floordiv,
           ast.Mod: operator.mod, ast.Pow: operator.pow}
_UNARYOPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}
_FUNCS = {"sqrt": math.sqrt, "log": math.log, "log10": math.log10,
          "abs": abs, "min": min, "max": max, "round": round}


def _depth(node, d=0):
    if d > MAX_DEPTH:
        raise UnsafeExpression("nesting too deep")
    for child in ast.iter_child_nodes(node):
        _depth(child, d + 1)


def _guard_pow(base, exp):
    # Blocks 9**9**9**9 before a giant int is ever materialised
    if abs(exp) > MAX_POW:
        raise UnsafeExpression("exponent exceeds limit")
    if base not in (0, 1, -1) and abs(exp) * math.log10(abs(base)) > 15:
        raise UnsafeExpression("result magnitude too large")


def _eval(node, variables):
    if isinstance(node, ast.Constant):
        if isinstance(node.value, bool) or not isinstance(node.value, (int, float)):
            raise UnsafeExpression("only numeric literals allowed")
        return node.value

    if isinstance(node, ast.Name):
        if node.id not in variables:               # default-deny: no globals, no builtins
            raise UnsafeExpression(f"unknown variable: {node.id}")
        return variables[node.id]

    if isinstance(node, ast.BinOp):
        op = type(node.op)
        if op not in _BINOPS:
            raise UnsafeExpression(f"operator not allowed: {op.__name__}")
        left, right = _eval(node.left, variables), _eval(node.right, variables)
        if op is ast.Pow:
            _guard_pow(left, right)
        if op in (ast.Div, ast.FloorDiv, ast.Mod) and right == 0:
            raise UnsafeExpression("division by zero")   # never silently return null
        return _BINOPS[op](left, right)

    if isinstance(node, ast.UnaryOp):
        op = type(node.op)
        if op not in _UNARYOPS:
            raise UnsafeExpression("unary operator not allowed")
        return _UNARYOPS[op](_eval(node.operand, variables))

    if isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name) or node.func.id not in _FUNCS:
            raise UnsafeExpression("function not allowed")
        if node.keywords:
            raise UnsafeExpression("keyword arguments not allowed")
        return _FUNCS[node.func.id](*[_eval(a, variables) for a in node.args])

    # ast.Attribute, ast.Subscript, ast.Lambda, ast.NamedExpr, ast.ListComp …
    raise UnsafeExpression(f"disallowed syntax: {type(node).__name__}")


def safe_eval(expr: str, variables: dict[str, float]) -> float:
    if not isinstance(expr, str) or len(expr) > MAX_LEN:
        raise UnsafeExpression("invalid or oversized expression")
    try:
        tree = ast.parse(expr, mode="eval")        # parse only — never compile/exec
    except SyntaxError as exc:
        raise UnsafeExpression(f"syntax error: {exc.msg}") from exc

    if sum(1 for _ in ast.walk(tree)) > MAX_NODES:
        raise UnsafeExpression("expression too complex")
    _depth(tree)

    result = _eval(tree.body, variables)
    if isinstance(result, bool) or not isinstance(result, (int, float)):
        raise UnsafeExpression("non-numeric result")
    if isinstance(result, float) and not math.isfinite(result):
        raise UnsafeExpression("non-finite result")   # NaN/Inf break JSON and downstream math
    return result
```

The `_FUNCS` dispatch is the whole allow-list surface. Anything not reachable by recursion here raises.

